import json, csv, re, statistics as st
from collections import defaultdict
tr = [json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows = list(csv.DictReader(open('data/scores.csv')))
print(len(tr), len(rows))
print('judge models:', set(t['judge_model'] for t in tr))
trd = {t['rating_id']: t for t in tr}
print('dup transcript ids', len(tr)-len(trd))
mism=[]
for r in rows:
    t = trd.get(r['rating_id'])
    if t is None: mism.append(('missing',r)); continue
    m = re.findall(r'FINAL SCORE:\s*(\d+)', t['judge_output'])
    fs = int(m[-1]) if m else None
    issues=[]
    if fs != int(r['score']): issues.append(('score',fs,r['score']))
    if t['response_id']!=r['response_id']: issues.append('resp')
    if str(t['session'])!=r['session']: issues.append(('session',t['session'],r['session']))
    if t['displayed_label']!=r['displayed_label']: issues.append(('label',t['displayed_label'],r['displayed_label']))
    mm = re.search(r'Displayed author: ([\w-]+)', t['judge_output'])
    if mm and mm.group(1)!=t['displayed_label']: issues.append(('output-label',mm.group(1),t['displayed_label']))
    if issues: mism.append((r['rating_id'], r['response_id'], issues))
print('issues:', len(mism))
for m in mism: print(m)
# multiple FINAL SCORE?
for t in tr:
    if len(re.findall(r'FINAL SCORE', t['judge_output']))!=1: print('multi', t['rating_id'])
# pairs
pairs=defaultdict(dict)
for r in rows: pairs[r['response_id']][r['displayed_label']]=int(r['score'])
print(len(pairs), [k for k,v in pairs.items() if len(v)!=2])
d=[v['atlas-7']-v['nova-3'] for v in pairs.values()]
print('per-pair diffs', d)
print('mean', st.mean(d), 'sd', st.stdev(d), 'n', len(d))
# sessions by label
c=defaultdict(list)
for r in rows: c[(r['session'],r['displayed_label'])].append(int(r['score']))
for k,v in sorted(c.items()): print(k, len(v), st.mean(v))
# session-1 label counts
print('session1 label counts', sum(1 for r in rows if r['session']=='1' and r['displayed_label']=='atlas-7'))
